// Process Google Drive files and extract company info
const files = $input.first().json.files || [];
console.log(`Found ${files.length} PDF files in Google Drive`);

if (files.length === 0) {
  console.log('No PDF files found in Google Drive');
  throw new Error('No PDF files found - workflow completed');
}

const results = [];

files.forEach(file => {
  console.log(`Processing file: ${file.name}`);

  // Extract company name from filename
  // Assuming filename format like "Company Research - ACME Corp.pdf" or "ACME Corp - Due Diligence.pdf"
  let companyName = file.name.replace(/\.pdf$/i, ''); // Remove .pdf extension

  // Try to extract company name from various patterns
  const patterns = [
    /(?:company research|due diligence)\s*[-:]\s*(.+)/i,
    /(.+?)\s*[-:]\s*(?:company research|due diligence)/i,
    /(.+?)\s*[-:]\s*(?:research|analysis|report)/i,
    /(.+)/  // fallback: use whole filename
  ];

  for (const pattern of patterns) {
    const match = companyName.match(pattern);
    if (match && match[1]) {
      companyName = match[1].trim();
      break;
    }
  }

  // Generate a unique task ID based on file ID
  const taskId = parseInt(file.id.replace(/\D/g, '').slice(-8)) || Math.floor(Math.random() * 1000000);

  results.push({
    task_id: taskId,
    company_name: companyName,
    file_id: file.id,
    file_name: file.name,
    file_size: file.size,
    modified_time: file.modifiedTime,
    drive_link: file.webViewLink,
    website: '', // Will be extracted from PDF content if available
    description: file.name // Initial description
  });

  console.log(`Prepared: ${companyName} (File: ${file.name})`);
});

console.log(`Processing ${results.length} company files`);
return results.map(item => ({ json: item }));

// Combine PDF text with company data and extract website
const companyData = $input.first().json;
const pdfData = $input.last().json;

const pdfText = pdfData.data || 'Could not extract PDF text';
console.log(`Extracted ${pdfText.length} characters from PDF: ${companyData.file_name}`);

// Try to extract website/URL from PDF content
let website = '';
const urlPatterns = [
  /(?:website|url|site)\s*:?\s*(https?:\/\/[^\s]+)/i,
  /(?:website|url|site)\s*:?\s*(www\.[^\s]+)/i,
  /(?:website|url|site)\s*:?\s*([a-zA-Z0-9.-]+\.[a-zA-Z]{2,})/i,
  /(https?:\/\/[^\s]+)/,
  /(www\.[^\s]+)/,
  /([a-zA-Z0-9.-]+\.(?:com|org|net|gov|edu|io|co)(?:\.[a-z]{2})?)/
];

for (const pattern of urlPatterns) {
  const match = pdfText.match(pattern);
  if (match && match[1]) {
    website = match[1];
    // Clean up the website URL
    if (!website.startsWith('http') && !website.startsWith('www')) {
      website = 'https://' + website;
    } else if (website.startsWith('www')) {
      website = 'https://' + website;
    }
    console.log(`Found website in PDF: ${website}`);
    break;
  }
}

if (!website) {
  console.log('No website found in PDF content');
}

// Prepare final data for database
const finalData = {
  task_id: companyData.task_id,
  company_name: companyData.company_name,
  website: website,
  pdf_text: pdfText,
  file_name: companyData.file_name,
  file_size: companyData.file_size,
  drive_link: companyData.drive_link,
  processed_date: new Date().toISOString()
};

console.log(`Final data prepared for: ${finalData.company_name}`);
console.log(`Website: ${finalData.website || 'Not found'}`);
console.log(`PDF text length: ${finalData.pdf_text.length} characters`);

return {
  json: finalData
};

// Log successful processing
const data = $input.first().json;

console.log(`✅ Successfully processed: ${data.company_name}`);
console.log(`📄 File: ${data.file_name}`);
console.log(`🌐 Website: ${data.website || 'Not found'}`);
console.log(`📊 PDF text: ${data.pdf_text.length} characters`);
console.log(`💾 Saved to database with task_id: ${data.task_id}`);

return {
  json: {
    status: 'success',
    company: data.company_name,
    file: data.file_name,
    website: data.website,
    text_length: data.pdf_text.length,
    task_id: data.task_id
  }
};
